/**
 * src/routeTree.gen.ts is generated by the TanStack Start Vite plugin and
 * gitignored, so a fresh clone (CI, a new contributor) can't typecheck
 * until it exists. Generate it with a one-off Vite build when it's missing.
 */
import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const www = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const routeTree = resolve(www, "src/routeTree.gen.ts");

if (!existsSync(routeTree)) {
  console.log("src/routeTree.gen.ts is missing; generating it with a Vite build…");
  const result = spawnSync("npx", ["vite", "build"], { cwd: www, stdio: "inherit" });
  if (result.status !== 0 || !existsSync(routeTree)) {
    console.error("Could not generate src/routeTree.gen.ts. Run `npm run dev` once, then retry.");
    process.exit(1);
  }
}
